INSERT INTO `dispute` (`id`, `checkoutId`, `raisedById`, `borrowerId`, `lenderId`, `status`, `title`, `description`, `depositAmount`, `beforePhotoUrl`, `afterPhotoUrl`, `aiVerdict`, `aiConfidence`, `aiNotes`, `raisedAt`, `updatedAt`) VALUES
('test_dispute_1', 'test_checkout_9', 'test_user_alice', 'test_user_bob', 'test_user_alice', 'OPEN', 'Lens scratched on return', 'The Canon EOS R5 was returned with visible scratches on the main lens element. Multiple hairline scratches are visible under light. This was not present at pickup.', 5000, NULL, NULL, 'lender_favored', 82, 'Surface abrasions detected on lens element. Optical path likely affected. High confidence damage occurred during borrow period.', '2026-05-19 18:00:00.000', '2026-05-23 14:28:41.198'),
('test_dispute_2', 'test_checkout_4', 'test_user_bob', 'test_user_carol', 'test_user_bob', 'ESCALATED', 'Headphones returned with broken headband', 'The Sony WH-1000XM5 headphones have a cracked headband on the left side. The borrower claims it was pre-existing but it clearly was not.', 2000, NULL, NULL, 'lender_favored', 67, 'Structural stress fracture detected on left headband arm. Consistent with impact or excessive force. Moderate confidence — requires visual verification.', '2026-05-14 18:00:00.000', '2026-05-23 14:28:41.217'),
('test_dispute_3', 'test_checkout_10', 'test_user_carol', 'test_user_dave', 'test_user_carol', 'UNDER_REVIEW', 'DJI drone gimbal malfunctioning after return', 'The DJI Air 3S drone gimbal is not stabilising correctly since the return. Footage now has visible shake. The borrower denies any incident.', 8000, NULL, NULL, 'inconclusive', 45, 'Gimbal motor telemetry shows calibration errors. Cannot confirm if caused by impact or firmware issue. Manual inspection recommended.', '2026-05-17 18:00:00.000', '2026-05-23 14:28:41.239'),
('test_dispute_4', 'test_checkout_11', 'test_user_bob', 'test_user_alice', 'test_user_bob', 'RESOLVED', 'MacBook returned with cracked screen corner', 'Small crack in the bottom-left corner of the MacBook Pro screen. Borrower acknowledged it happened during transport.', 4000, NULL, NULL, 'lender_favored', 91, 'Physical impact fracture detected in display panel corner. Pattern consistent with drop or sharp impact. High confidence damage occurred during borrow period.', '2026-04-27 18:00:00.000', '2026-05-23 14:28:41.257');
