INSERT INTO `mentor` (`id`, `name`, `handle`, `avatar`, `specialty`, `category`, `bio`, `tags`, `rating`, `sessions`, `pricePerSession`, `available`, `responseTime`, `createdAt`, `subcategories`, `userId`) VALUES
('cmpcujaw60000kdzq1d2azgpk', 'Arif Hossain', '@arif_photo', 'AH', 'DSLR & Mirrorless Cameras', 'Cameras', 'Professional photographer with 8 years of experience. I teach composition, lighting, and advanced camera settings in plain language.', '[\"Canon\", \"Sony\", \"Nikon\"]', '4.90', 47, 500, 1, 'Usually replies in 1hr', '2026-05-19 16:27:31.686', '[]', NULL),
('cmpcujaxc0001kdzqw685ywyx', 'Nadia Islam', '@nadia_lens', 'NI', 'Landscape & Portrait Photography', 'Cameras', 'Award-winning portrait photographer. I help beginners get stunning results from day one with any mirrorless or DSLR.', '[\"Portrait\", \"Lighting\", \"Editing\"]', '4.80', 31, 400, 1, 'Usually replies in 2hr', '2026-05-19 16:27:31.728', '[]', NULL),
('cmpcujaxf0002kdzqiaoqprt7', 'Tanvir Ahmed', '@tanvir_dev', 'TA', 'macOS, Final Cut Pro & DaVinci', 'Tech & Electronics', 'Apple-certified professional. I teach video editing workflows, macOS productivity, and creative software from scratch.', '[\"MacBook\", \"Final Cut\", \"DaVinci\"]', '4.70', 22, 300, 1, 'Usually replies in 30min', '2026-05-19 16:27:31.731', '[]', NULL),
('cmpcujaxj0003kdzqniow7zoi', 'Alex Smith', '@alexsmith', 'AL', 'Acoustic Guitar & Songwriting', 'Musical Instruments', 'Music teacher with 12 years of experience. I take students from complete beginner to playing their first song in one session.', '[\"Acoustic\", \"Classical\", \"Songwriting\"]', '4.90', 63, 350, 1, 'Usually replies in 1hr', '2026-05-19 16:27:31.736', '[]', NULL),
('cmpcujaxn0004kdzqhezvp75v', 'Rahul Sharma', '@rahulsharma', 'RS', 'Drone Piloting & Aerial Photography', 'Cameras', 'CAA certified drone pilot. I cover safety regulations, flight controls, and cinematic techniques for professional aerial footage.', '[\"DJI\", \"Aerial\", \"Safety\"]', '4.90', 19, 800, 1, 'Usually replies in 3hr', '2026-05-19 16:27:31.740', '[]', NULL),
('cmpcujaxr0005kdzqpx948exm', 'Sara Khan', '@sarakhan_dev', 'SK', 'Video Production & Lighting', 'Tech & Electronics', 'Freelance video producer specializing in corporate content. I teach lighting setups, camera movement, and post-production basics.', '[\"Video\", \"Lighting\", \"Production\"]', '4.60', 14, 450, 0, 'Currently unavailable', '2026-05-19 16:27:31.743', '[]', NULL),
('cmpcujaxu0006kdzqkq2kg9b1', 'Mike Davis', '@mikedavis', 'MD', 'Power Tools & Home Renovation', 'Tools & Equipment', 'Licensed contractor with 15 years of experience. I make power tools approachable and safe for complete beginners.', '[\"Drill\", \"Safety\", \"DIY\"]', '4.60', 38, 250, 1, 'Usually replies in 1hr', '2026-05-19 16:27:31.746', '[]', NULL),
('cmpcujaxx0007kdzqwthinok0', 'Priya Patel', '@priyapatel', 'PP', 'Mirrorless Systems & Event Photography', 'Cameras', 'Wedding and event photographer. I specialise in fast-paced shooting, autofocus systems, and colour grading for memorable results.', '[\"Sony\", \"Events\", \"Colour\"]', '4.80', 26, 550, 1, 'Usually replies in 2hr', '2026-05-19 16:27:31.749', '[]', NULL),
