('cmpcv9q7r000b9xh4opt9n8cz', 'md-yashfin-hossain-z6v3t', 'Md Yashfin Hossain', 'Miscellaneous', 'asdasd', 'asdasd', '[]', 'http://localhost:3000/dashboard/my-items', NULL, '12312', '123123', '2026-05-19 16:48:04.590', '2026-05-19 16:48:04.590', NULL, 122, 323, '[]', 'test_user_alice'),
('test_prod_alice_1', 'canon-eos-r5-alice', 'Canon EOS R5 Camera', 'Photography & Film', 'Dhanmondi, Dhaka', 'Professional mirrorless camera with RF 24-105mm f/4L lens. 45MP sensor, 8K video capable. Includes 2 batteries, charger, and camera bag.', '[\"45MP Full-Frame Sensor\", \"8K RAW Video\", \"RF 24-105mm f/4L Lens\", \"2 Batteries\", \"Camera Bag\"]', '/placeholder.png', 'Please handle with care. Clean the lens before returning.', 'TK 80,000', 'TK 5,000', '2026-05-19 16:45:39.114', '2026-05-23 14:28:40.849', 'DSLR & Mirrorless Cameras', 800, 5000, '[\"Heavy with lens attached\", \"Battery life ~250 shots\"]', 'test_user_alice'),
('test_prod_alice_2', 'camping-tent-alice', '4-Person Camping Tent', 'Outdoor & Adventure', 'Dhanmondi, Dhaka', 'Waterproof dome tent with separate sleeping and living areas. Easy 10-minute setup. Includes rainfly, stakes, and carry bag.', '[\"4-Person Capacity\", \"Waterproof\", \"Quick Setup\", \"Rainfly Included\", \"Stakes & Bag\"]', '/placeholder.png', 'Please dry before packing. Return in carry bag.', 'TK 8,000', 'TK 1,000', '2026-05-19 16:45:39.122', '2026-05-23 14:28:40.873', 'Camping & Hiking', 350, 1500, '[\"Slightly heavy at 4.5kg\"]', 'test_user_alice'),
('test_prod_alice_3', 'gopro-hero12-alice', 'GoPro Hero 12 Black', 'Photography & Film', 'Dhanmondi, Dhaka', 'Latest GoPro with 5.3K video, HyperSmooth 6.0 stabilization, and waterproof to 10m. Includes chest mount, head strap, helmet mount, and 2 batteries.', '[\"5.3K Video\", \"HyperSmooth 6.0\", \"Waterproof 10m\", \"3 Mounts\", \"2 Batteries\"]', '/placeholder.png', 'Return with all mounts. Format the card before returning.', 'TK 45,000', 'TK 3,000', '2026-05-19 22:32:58.575', '2026-05-23 14:28:40.877', 'Action Cameras', 400, 2000, '[\"No viewfinder\", \"Lens prone to fogging in humidity\"]', 'test_user_alice'),
('test_prod_alice_4', 'softbox-lighting-kit-alice', '3-Point Softbox Studio Lighting Kit', 'Photography & Film', 'Dhanmondi, Dhaka', 'Professional 3-light softbox kit â€” 2Ã—90W key/fill lights + 1Ã—45W background light, all with stands and diffusers. Perfect for portraits, product shoots, and YouTube.', '[\"3 Lights Included\", \"Adjustable Color Temp\", \"Collapsible Stands\", \"Carry Bag\", \"Remote Control\"]', '/placeholder.png', 'Handle bulbs carefully. Return all stands and diffusers.', 'TK 20,000', 'TK 2,000', '2026-05-19 22:32:58.586', '2026-05-23 14:28:40.880', 'Studio Lighting & Equipment', 350, 1500, '[\"Setup takes ~20 minutes\", \"Heavy bag (8kg total)\"]', 'test_user_alice'),
('test_prod_alice_5', 'casio-keyboard-alice', 'Casio CT-X700 Portable Keyboard', 'Music & Audio', 'Dhanmondi, Dhaka', '61-key portable keyboard with 600 tones, 180 rhythms, and built-in speakers. Runs on batteries or AC adapter. Great for beginners and rehearsals.', '[\"61 Keys\", \"600 Tones\", \"180 Auto-Rhythms\", \"Battery or AC\", \"Built-In Speakers\"]', '/placeholder.png', 'Return with AC adapter. Keep away from moisture.', 'TK 12,000', 'TK 1,000', '2026-05-19 22:32:58.588', '2026-05-23 14:28:40.883', 'Keyboards & Piano', 200, 800, '[\"Not weighted keys\"]', 'test_user_alice'),
('test_prod_alice_6', 'benq-projector-alice', 'BenQ TH685P 4K Projector', 'Tech & Electronics', 'Dhanmondi, Dhaka', 'Full HD 1080p projector with 4K HDR input, 3500 lumens brightness. Ideal for outdoor movies, presentations, and events. HDMI + USB-C input.', '[\"3500 Lumens\", \"4K HDR Input\", \"Low Input Lag\", \"HDMI & USB-C\", \"Tripod Mount\"]', '/placeholder.png', 'Allow lamp to cool 5 min before packing. Return with remote.', 'TK 60,000', 'TK 5,000', '2026-05-19 22:32:58.591', '2026-05-23 14:28:40.887', 'Projectors & Displays', 700, 4000, '[\"No built-in battery (mains only)\", \"Fan noise in quiet rooms\"]', 'test_user_alice'),
('test_prod_alice_7', 'sea-kayak-alice', '2-Person Touring Kayak', 'Outdoor & Adventure', 'Dhanmondi, Dhaka', 'Stable tandem kayak suitable for rivers and calm coastal water. 5.2m length, includes 2 paddles, 2 life jackets, and dry bags.', '[\"2-Person Capacity\", \"2 Paddles\", \"2 Life Jackets\", \"Dry Bags\", \"Rudder System\"]', '/placeholder.png', 'Rinse with fresh water after sea use. Return paddles and life jackets.', 'TK 50,000', 'TK 5,000', '2026-05-19 22:32:58.595', '2026-05-23 14:28:40.890', 'Water Sports', 500, 3000, '[\"Requires vehicle with roof rack for transport\", \"5.2m length\"]', 'test_user_alice'),
('test_prod_alice_8', 'sony-a7iv-alice', 'Sony A7 IV Mirrorless Camera', 'Photography & Film', 'Dhanmondi, Dhaka', '33MP full-frame sensor, 4K 60fps video, 759-point AF system. Includes Sony 28-70mm f/3.5-5.6 kit lens and 2 batteries.', '[\"33MP Full-Frame\", \"4K 60fps Video\", \"759-Point AF\", \"Dual Card Slots\", \"2 Batteries\"]', '/placeholder.png', 'Do not change lenses in dusty environments.', 'TK 70,000', 'TK 5,000', '2026-05-19 22:32:58.598', '2026-05-23 14:28:40.893', 'DSLR & Mirrorless Cameras', 750, 4500, '[\"Kit lens not weather-sealed\", \"Menu system can be complex\"]', 'test_user_alice'),
('test_prod_bob_1', 'yamaha-guitar-bob', 'Yamaha F310 Acoustic Guitar', 'Music & Audio', 'Banani, Dhaka', 'Full-size acoustic guitar in excellent condition. Great for beginners and intermediate players. Includes gig bag and extra strings.', '[\"Full-Size Dreadnought\", \"Spruce Top\", \"Gig Bag\", \"Extra Strings Set\"]', '/placeholder.png', 'Tune before returning. Handle the neck carefully.', 'TK 6,000', 'TK 500', '2026-05-19 16:45:39.125', '2026-05-23 14:28:40.896', 'Guitar & Bass', 200, 800, '[\"Action slightly high for complete beginners\"]', 'test_user_bob'),
('test_prod_bob_2', 'sony-headphones-bob', 'Sony WH-1000XM5 Headphones', 'Tech & Electronics', 'Banani, Dhaka', 'Industry-leading noise cancelling wireless headphones. 30-hour battery, multipoint connection, crystal-clear call quality.', '[\"30-Hour Battery\", \"Noise Cancelling\", \"Multipoint Connection\", \"USB-C Charging\", \"Case Included\"]', '/placeholder.png', 'Charge to 100% before returning. Do not bend the headband.', 'TK 35,000', 'TK 2,000', '2026-05-19 16:45:39.128', '2026-05-23 14:28:40.899', 'Networking & Tech Setup', 300, 2000, '[\"Not foldable\"]', 'test_user_bob'),
('test_prod_bob_3', 'ps5-bob', 'PlayStation 5 Console + 2 Controllers', 'Gaming', 'Banani, Dhaka', 'PS5 Disc edition with 2 DualSense controllers, 5 AAA games (Spider-Man 2, God of War RagnarÃ¶k, FIFA 24, GTA V, Mortal Kombat 1). HDMI cable included.', '[\"2 DualSense Controllers\", \"5 Game Discs\", \"HDMI 2.1 Cable\", \"825GB SSD\", \"4K@120fps\"]', '/placeholder.png', 'Do not leave in standby for extended periods. Return all discs.', 'TK 60,000', 'TK 5,000', '2026-05-19 22:32:58.624', '2026-05-23 14:28:40.904', 'Consoles & Controllers', 450, 3000, '[\"Large unit, needs good ventilation\"]', 'test_user_bob'),
('test_prod_bob_4', 'macbook-pro-14-bob', 'MacBook Pro 14\" M3 Pro', 'Tech & Electronics', 'Banani, Dhaka', 'Apple MacBook Pro 14\" with M3 Pro chip, 18GB unified memory, 512GB SSD. Ideal for video editing, design, and development. Includes 140W USB-C charger.', '[\"M3 Pro Chip\", \"18GB RAM\", \"512GB SSD\", \"140W USB-C Charger\", \"MagSafe Port\"]', '/placeholder.png', 'Sign in with a guest account only. Log out before returning.', 'TK 200,000', 'TK 10,000', '2026-05-19 22:32:58.628', '2026-05-23 14:28:40.907', 'Computers & Laptops', 900, 6000, '[\"No Windows compatibility without Bootcamp\"]', 'test_user_bob'),
('test_prod_bob_5', 'meta-quest-3-bob', 'Meta Quest 3 VR Headset', 'Gaming', 'Banani, Dhaka', 'Standalone VR headset with mixed reality passthrough, 4K display, and 128GB storage. Comes with 2 Touch Plus controllers and charging dock.', '[\"4K Display\", \"Mixed Reality\", \"128GB Storage\", \"2 Controllers\", \"Charging Dock\"]', '/placeholder.png', 'Wipe lenses with included cloth only. Return all accessories.', 'TK 55,000', 'TK 5,000', '2026-05-19 22:32:58.631', '2026-05-23 14:28:40.910', 'VR & AR Headsets', 600, 4000, '[\"2.5â€“3hr battery on intensive use\"]', 'test_user_bob'),
('test_prod_bob_6', 'jbl-pa-speaker-bob', 'JBL EON712 Powered PA Speaker', 'Events & Party', 'Banani, Dhaka', '1300W active PA speaker with 12\" woofer, built-in mixer (3 channels), Bluetooth, and DSP. Handles 200+ person events. Includes speaker stand.', '[\"1300W Output\", \"3-Channel Mixer\", \"Bluetooth\", \"Speaker Stand\", \"XLR & TRS Inputs\"]', '/placeholder.png', 'Return with cover. Do not run at max volume for extended periods.', 'TK 80,000', 'TK 5,000', '2026-05-19 22:32:58.634', '2026-05-23 14:28:40.913', 'Sound & PA Systems', 550, 3000, '[\"22kg â€” needs two people to carry\"]', 'test_user_bob'),
('test_prod_bob_7', 'nebula-projector-bob', 'Anker Nebula Cosmos Max Projector', 'Tech & Electronics', 'Banani, Dhaka', '4K Android projector with 1500 ANSI lumens, built-in Dolby Audio speakers, Android TV, and autofocus. Perfect for outdoor movies and watch parties.', '[\"4K Resolution\", \"1500 ANSI Lumens\", \"Dolby Audio\", \"Android TV\", \"Autofocus\"]', '/placeholder.png', 'Allow to cool before moving. Return remote and power cable.', 'TK 65,000', 'TK 6,000', '2026-05-19 22:32:58.637', '2026-05-23 14:28:40.916', 'Projectors & Displays', 500, 3500, '[\"Needs dark environment for best results\"]', 'test_user_bob'),
('test_prod_bob_8', 'rode-wireless-go-bob', 'Rode Wireless GO II Dual Microphone', 'Music & Audio', 'Banani, Dhaka', 'Dual-channel compact wireless microphone system. 200m range, 7-hour battery, built-in recording backup. Perfect for interviews, vlogs, and events.', '[\"Dual Transmitters\", \"200m Range\", \"7-Hour Battery\", \"Built-In Recording\", \"USB-C Charging\"]', '/placeholder.png', 'Return all transmitters and receiver. Handle connectors gently.', 'TK 30,000', 'TK 2,000', '2026-05-19 22:32:58.639', '2026-05-23 14:28:40.920', 'Studio & Recording Equipment', 300, 1500, '[\"Wind noise in outdoor use without windshield\"]', 'test_user_bob'),
('test_prod_carol_1', 'bosch-drill-carol', 'Bosch Power Drill Set', 'Tools & DIY', 'Gulshan, Dhaka', 'Professional 18V cordless drill with 2 batteries and full accessory kit (50 bits and drill heads). Perfect for home improvement projects.', '[\"18V Cordless\", \"2 Batteries\", \"50-Piece Bit Set\", \"Carrying Case\", \"LED Work Light\"]', '/placeholder.png', 'Return all bits. Charge batteries before returning.', 'TK 15,000', 'TK 1,500', '2026-05-19 16:45:39.131', '2026-05-23 14:28:40.923', 'Power Tools', 400, 2500, '[\"Heavy at 1.9kg with battery\"]', 'test_user_carol'),
('test_prod_carol_2', 'dji-drone-carol', 'DJI Air 3S Drone', 'Photography & Film', 'Gulshan, Dhaka', 'Advanced drone with 4K/120fps camera, 46-minute flight time, and omnidirectional obstacle sensing. Comes with 3 batteries and ND filter kit.', '[\"4K/120fps Camera\", \"46-Min Flight Time\", \"Obstacle Sensing\", \"3 Batteries\", \"ND Filter Kit\"]', '/placeholder.png', 'Must have drone licence. Return all batteries charged.', 'TK 120,000', 'TK 10,000', '2026-05-19 16:45:39.135', '2026-05-23 14:28:40.926', 'Drones & Aerial Photography', 1200, 8000, '[\"Requires drone registration\", \"No-fly zones in Dhaka city centre\"]', 'test_user_carol'),
('test_prod_carol_3', 'kitchenaid-mixer-carol', 'KitchenAid Artisan Stand Mixer', 'Kitchen & Cooking', 'Gulshan, Dhaka', '5-quart tilt-head stand mixer with 10 speeds, dough hook, flat beater, and wire whip. Perfect for baking large batches of bread, cakes, and pastry.', '[\"5-Quart Bowl\", \"10 Speed Settings\", \"Dough Hook\", \"Flat Beater\", \"Wire Whip\"]', '/placeholder.png', 'Return clean and dry. All attachments must be returned.', 'TK 50,000', 'TK 3,000', '2026-05-19 22:32:58.649', '2026-05-23 14:28:40.928', 'Specialty Cooking Equipment', 350, 2000, '[\"Heavy at 11kg â€” not portable\", \"Bowl gets hot with long mixing\"]', 'test_user_carol'),
('test_prod_carol_4', 'delonghi-espresso-carol', 'De\'Longhi Dinamica Espresso Machine', 'Kitchen & Cooking', 'Gulshan, Dhaka', 'Bean-to-cup espresso machine with built-in grinder, milk frother, and 15-bar pump. Makes espresso, cappuccino, and latte at the touch of a button.', '[\"Built-In Grinder\", \"15-Bar Pump\", \"Milk Frother\", \"Hot Water Spout\", \"Removable Brew Unit\"]', '/placeholder.png', 'Run a cleaning cycle before returning. Return with bean hopper empty.', 'TK 80,000', 'TK 5,000', '2026-05-19 22:32:58.652', '2026-05-23 14:28:40.932', 'Barista & Coffee Equipment', 450, 3000, '[\"Needs descaling every 2â€“3 months\", \"Loud grinder\"]', 'test_user_carol'),
('test_prod_carol_5', 'makita-circular-saw-carol', 'Makita 185mm Circular Saw', 'Tools & DIY', 'Gulshan, Dhaka', '1200W corded circular saw with laser guide, dust blower, and rip fence. Cuts up to 66mm depth. Includes 2 blades (wood + multipurpose).', '[\"1200W Motor\", \"Laser Guide\", \"Dust Blower\", \"Rip Fence\", \"2 Blades Included\"]', '/placeholder.png', 'Return blades. Wear safety glasses while using.', 'TK 18,000', 'TK 2,000', '2026-05-19 22:32:58.655', '2026-05-23 14:28:40.937', 'Power Tools', 400, 2500, '[\"Corded only â€” needs power nearby\"]', 'test_user_carol'),
('test_prod_carol_6', 'ring-light-carol', '18\" LED Ring Light + Tripod Kit', 'Photography & Film', 'Gulshan, Dhaka', '18-inch bi-colour LED ring light (3200â€“5600K) with 2.1m tripod, phone holder, and remote. Ideal for selfies, reels, streaming, and video calls.', '[\"18\\\" Diameter\", \"3200â€“5600K Colour Temp\", \"2.1m Tripod\", \"Phone Holder\", \"Remote Control\"]', '/placeholder.png', 'Return tripod fully collapsed. Handle the ring gently.', 'TK 8,000', 'TK 1,000', '2026-05-19 22:32:58.658', '2026-05-23 14:28:40.941', 'Studio Lighting & Equipment', 200, 800, '[\"Not suitable for large studio shoots\"]', 'test_user_carol'),
('test_prod_carol_7', 'epson-laser-projector-carol', 'Epson EB-L200F Laser Projector', 'Tech & Electronics', 'Gulshan, Dhaka', 'Full HD laser projector with 4500 lumens â€” works in fully lit rooms. No lamp to replace. 20,000-hour light source. HDMI, USB, and wireless projection.', '[\"4500 Lumens\", \"Laser Light Source\", \"20,000hr Lifespan\", \"Wireless Projection\", \"HDMI & USB\"]', '/placeholder.png', 'Do not block ventilation. Return with all cables.', 'TK 150,000', 'TK 10,000', '2026-05-19 22:32:58.662', '2026-05-23 14:28:40.944', 'Projectors & Displays', 1000, 6000, '[\"Large and heavy (4.7kg)\"]', 'test_user_carol'),
('test_prod_carol_8', 'brother-sewing-machine-carol', 'Brother CS6000i Sewing Machine', 'Art & Craft', 'Gulshan, Dhaka', '60-stitch computerised sewing machine with LCD display, automatic needle threader, and free arm. Great for garments, home textiles, and quilting.', '[\"60 Built-In Stitches\", \"LCD Display\", \"Auto Needle Threader\", \"Free Arm\", \"7 Presser Feet\"]', '/placeholder.png', 'Return with all presser feet. Thread must be removed before return.', 'TK 25,000', 'TK 2,000', '2026-05-19 22:32:58.665', '2026-05-23 14:28:40.947', 'Sewing & Textile', 250, 1500, '[\"Comes with manual in English only\"]', 'test_user_carol'),
('test_prod_dave_1', 'trek-bicycle-dave', 'Trek Marlin 5 Mountain Bicycle', 'Outdoor & Adventure', 'Uttara, Dhaka', 'Versatile hardtail mountain bike with 21-speed Shimano drivetrain. Suitable for trails and urban commuting. Helmet and lock included.', '[\"21-Speed Shimano\", \"Hardtail Frame\", \"Disc Brakes\", \"Helmet Included\", \"Lock Included\"]', '/placeholder.png', 'Return clean. Lock the bike when not in use.', 'TK 40,000', 'TK 2,000', '2026-05-19 16:45:39.139', '2026-05-23 14:28:40.951', 'Cycling', 500, 3000, '[\"Size L â€” best for riders 175â€“185cm\"]', 'test_user_dave'),
('test_prod_dave_2', 'ipad-pro-dave', 'iPad Pro 12.9\" (M2)', 'Tech & Electronics', 'Uttara, Dhaka', 'Latest iPad Pro with Apple Pencil 2nd gen and Magic Keyboard. 256GB storage, Wi-Fi + Cellular. Ideal for design, drawing, and video editing.', '[\"M2 Chip\", \"256GB Storage\", \"Apple Pencil 2nd Gen\", \"Magic Keyboard\", \"Wi-Fi + Cellular\"]', '/placeholder.png', 'Return with full charge. Do not install apps without permission.', 'TK 120,000', 'TK 8,000', '2026-05-19 16:45:39.142', '2026-05-23 14:28:40.955', 'Tablets & iPads', 600, 4000, '[\"Magic Keyboard adds significant weight\"]', 'test_user_dave'),
('test_prod_dave_3', 'cricket-set-dave', 'Full Cricket Equipment Set', 'Sports & Fitness', 'Uttara, Dhaka', 'Complete cricket set: English willow bat (Grade 2), full set of pads, gloves, helmet, chest guard, and ball (leather + tennis). Fits adults and teens.', '[\"English Willow Bat\", \"Full Pad Set\", \"Helmet\", \"Gloves\", \"Leather + Tennis Ball\"]', '/placeholder.png', 'Oil the bat face before returning. Return all items in the kit bag.', 'TK 25,000', 'TK 2,000', '2026-05-19 22:32:58.692', '2026-05-23 14:28:40.958', 'Team Sports Equipment', 400, 2000, '[\"Bat handle may need re-gripping after heavy use\"]', 'test_user_dave'),
('test_prod_dave_4', 'dumbbells-dave', 'Bowflex SelectTech 552 Adjustable Dumbbells', 'Sports & Fitness', 'Uttara, Dhaka', 'Pair of adjustable dumbbells from 2kg to 24kg each (15 settings). Replace a full rack of dumbbells. Perfect for home workouts.', '[\"2â€“24kg Each\", \"15 Weight Settings\", \"Space-Saving Design\", \"Pair Included\", \"Storage Trays\"]', '/placeholder.png', 'Always use with the selector dial fully clicked. Return in trays.', 'TK 30,000', 'TK 3,000', '2026-05-19 22:32:58.696', '2026-05-23 14:28:40.962', 'Gym & Weightlifting Equipment', 300, 2000, '[\"Bulkier than fixed dumbbells at each weight\"]', 'test_user_dave'),
('test_prod_dave_5', 'weber-bbq-dave', 'Weber Q1200 Portable Gas BBQ', 'Kitchen & Cooking', 'Uttara, Dhaka', 'Compact but powerful 2.2kW gas grill with cast iron grate, 1276cmÂ² cooking area, and folding side tables. Perfect for rooftop, garden, or camping barbecues.', '[\"2.2kW Burner\", \"Cast Iron Grate\", \"1276cmÂ² Area\", \"Folding Tables\", \"Grease Catch Pan\"]', '/placeholder.png', 'Clean the grate after use. Return lid closed and gas disconnected.', 'TK 25,000', 'TK 2,000', '2026-05-19 22:32:58.699', '2026-05-23 14:28:40.965', 'Outdoor BBQ & Grilling', 350, 2000, '[\"Gas cylinder not included â€” user must bring their own\"]', 'test_user_dave'),
('test_prod_dave_6', 'hammock-dave', 'ENO DoubleNest Camping Hammock + Tree Straps', 'Outdoor & Adventure', 'Uttara, Dhaka', 'Lightweight double hammock (136kg capacity) with Atlas tree straps. Packs into a 4Ã—15cm pouch. Suitable for two adults or one person sleeping.', '[\"136kg Capacity\", \"Atlas Tree Straps\", \"Packs to 4Ã—15cm Pouch\", \"Quick Setup\", \"Compression Sack\"]', '/placeholder.png', 'Dry before packing. Check straps for wear.', 'TK 6,000', 'TK 500', '2026-05-19 22:32:58.702', '2026-05-23 14:28:40.970', 'Camping & Hiking', 150, 500, '[\"Needs two trees at least 4m apart\"]', 'test_user_dave'),
('test_prod_dave_7', 'karcher-pressure-washer-dave', 'K archer K4 Premium Pressure Washer', 'Tools & DIY', 'Uttara, Dhaka', '130 bar pressure washer with 1800W motor, Vario Power spray lance, Dirt Blaster lance, and 8m hose. Cleans cars, driveways, rooftops, and walls.', '[\"130 Bar Pressure\", \"1800W Motor\", \"Vario Power Lance\", \"Dirt Blaster Lance\", \"8m Hose\"]', '/placeholder.png', 'Release water pressure before disconnecting. Return hose coiled.', 'TK 35,000', 'TK 3,000', '2026-05-19 22:32:58.704', '2026-05-23 14:28:40.975', 'Power Tools', 500, 3000, '[\"Corded â€” needs outdoor power point\"]', 'test_user_dave'),
('test_prod_dave_8', 'wilson-tennis-dave', 'Wilson Pro Staff RF97 Tennis Set', 'Sports & Fitness', 'Uttara, Dhaka', 'Roger Federer signature racket (strung) + 2nd racket for doubles, 4 premium tennis balls, overgrips, and a racket bag. Perfect for club and recreational play.', '[\"2 Rackets (Strung)\", \"4 Premium Balls\", \"Overgrips\", \"Racket Bag\", \"Dampeners\"]', '/placeholder.png', 'Return rackets in the bag. Do not leave in direct sun.', 'TK 20,000', 'TK 1,500', '2026-05-19 22:32:58.707', '2026-05-23 14:28:40.979', 'Racquet Sports', 200, 1000, '[\"RF97 is 340g â€” heavier than average\"]', 'test_user_dave');


